        'async function probarConexionShopifyUI(boton) {\n  const resultado = document.getElementById(\'shopifyResultado\');\n  document.getElementById(\'shopifyError\').textContent = \'\';\n  resultado.innerHTML = \'\';\n  await conBloqueoDeBoton(boton, async () => {\n    try {\n      const r = await api(\'/api/shopify/probar-conexion\', { method: \'POST\' });\n      resultado.innerHTML = `<p style="font-size:13px; color:var(--trace); margin-top:10px;">✅ ${escapeHtml(r.mensaje)}</p>`;\n    } catch (e) {\n      document.getElementById(\'shopifyError\').textContent = e.message;\n    }\n  });\n}\n\nfunction renderGeotabAdmin(tabsHtml, config) {',
        'async function probarConexionShopifyUI(boton) {\n  const resultado = document.getElementById(\'shopifyResultado\');\n  document.getElementById(\'shopifyError\').textContent = \'\';\n  resultado.innerHTML = \'\';\n  await conBloqueoDeBoton(boton, async () => {\n    try {\n      const r = await api(\'/api/shopify/probar-conexion\', { method: \'POST\' });\n      resultado.innerHTML = `<p style="font-size:13px; color:var(--trace); margin-top:10px;">✅ ${escapeHtml(r.mensaje)}</p>`;\n    } catch (e) {\n      document.getElementById(\'shopifyError\').textContent = e.message;\n    }\n  });\n}\n\nfunction renderDSCoreAdmin(tabsHtml, config) {\n  document.getElementById(\'modalContent\').innerHTML = `\n    <button class="close-btn" onclick="cerrarModal()">cerrar</button>\n    <h2>Administrar</h2>\n    ${tabsHtml}\n    <p style="font-size:12px; color:var(--muted); margin-bottom:16px;">\n      Conexión con DS Core (Dentsply Sirona) para que el estudiante importe su pedido con el código que le da el maestro, en vez de escribirlo a mano. Se conecta UNA sola vez, como cuenta de servicio del laboratorio -- no es un login por estudiante.\n      Necesitas el Client ID que te dio Dentsply Sirona al aprobarte el acceso en el <a href="https://open.dscore.com" target="_blank" style="color:var(--copper);">portal de desarrolladores</a> (persona LAB), y poner esta URL como "Redirect URL" de tu app ahí:\n      <br /><code style="font-size:11px; word-break:break-all;">${location.origin}/api/laboratorio/dscore/oauth/callback</code>\n    </p>\n    <div class="field"><label>Host base (Base Host)</label><input id="ds_host" value="${config.base_host ? escapeHtml(config.base_host) : \'\'}" placeholder="https://api.r2.dscore.com (sandbox)" /></div>\n    <div class="field"><label>Client ID</label><input id="ds_client_id" value="${config.client_id ? escapeHtml(config.client_id) : \'\'}" placeholder="Client ID de DS Core" /></div>\n    <div class="field"><label>Client Secret ${config.tiene_client_secret ? \'<span style="color:var(--muted); font-weight:400; text-transform:none;">(ya hay uno guardado — déjalo vacío para no cambiarlo)</span>\' : \'\'}</label><input type="password" id="ds_client_secret" placeholder="${config.tiene_client_secret ? \'••••••••\' : \'\'}" /></div>\n    <button class="primary" style="width:100%; margin: 10px 0;" onclick="guardarConfigDSCoreUI(this)">Guardar</button>\n\n    <div style="border-top:1px solid rgba(155,157,159,0.3); padding-top:14px; margin-top:6px;">\n      <p style="font-size:12px; color:var(--muted);">\n        Estatus: ${config.conectado ? \'✅ Conectado\' : \'⚠️ Todavía no conectado — guarda los datos de arriba primero, luego dale abajo.\'}\n      </p>\n      <div style="display:flex; gap:8px;">\n        <button class="secondary" style="flex:1;" onclick="conectarDSCoreOAuth()">Conectar con DS Core</button>\n        ${config.conectado ? `<button class="secondary" style="flex:1;" onclick="probarConexionDSCoreUI(this)">Probar conexión</button>` : \'\'}\n        ${config.conectado ? `<button class="secondary" style="flex:1; color:var(--urgente);" onclick="desconectarDSCoreUI(this)">Desconectar</button>` : \'\'}\n      </div>\n    </div>\n    <div id="dscoreError" class="error-msg"></div>\n    <div id="dscoreResultado"></div>\n  `;\n  abrirModal(true);\n}\n\nasync function guardarConfigDSCoreUI(boton) {\n  const payload = {\n    base_host: document.getElementById(\'ds_host\').value.trim(),\n    client_id: document.getElementById(\'ds_client_id\').value.trim() || null,\n    client_secret: document.getElementById(\'ds_client_secret\').value || null,\n  };\n  if (!payload.base_host) {\n    document.getElementById(\'dscoreError\').textContent = \'Falta el host base de DS Core\';\n    return;\n  }\n  await conBloqueoDeBoton(boton, async () => {\n    try {\n      await api(\'/api/laboratorio/dscore/config\', { method: \'POST\', body: JSON.stringify(payload) });\n      mostrarExito(\'Configuración de DS Core guardada exitosamente\');\n      await cambiarAdminTab(\'dscore\');\n    } catch (e) {\n      document.getElementById(\'dscoreError\').textContent = e.message;\n    }\n  });\n}\n\nasync function conectarDSCoreOAuth() {\n  document.getElementById(\'dscoreError\').textContent = \'\';\n  try {\n    const r = await api(\'/api/laboratorio/dscore/oauth/iniciar\');\n    window.location.href = r.url; // manda al navegador a autorizar en DS Core -- regresa solo al terminar\n  } catch (e) {\n    document.getElementById(\'dscoreError\').textContent = e.message;\n  }\n}\n\nasync function probarConexionDSCoreUI(boton) {\n  const resultado = document.getElementById(\'dscoreResultado\');\n  document.getElementById(\'dscoreError\').textContent = \'\';\n  resultado.innerHTML = \'\';\n  await conBloqueoDeBoton(boton, async () => {\n    try {\n      const r = await api(\'/api/laboratorio/dscore/probar-conexion\', { method: \'POST\' });\n      resultado.innerHTML = `<p style="font-size:13px; color:var(--trace); margin-top:10px;">✅ ${escapeHtml(r.mensaje)}</p>`;\n    } catch (e) {\n      document.getElementById(\'dscoreError\').textContent = e.message;\n    }\n  });\n}\n\nasync function desconectarDSCoreUI(boton) {\n  if (!confirm(\'¿Desconectar DS Core? El estudiante ya no podrá importar pedidos por código hasta que se vuelva a conectar.\')) return;\n  await conBloqueoDeBoton(boton, async () => {\n    try {\n      await api(\'/api/laboratorio/dscore/desconectar\', { method: \'POST\' });\n      await cambiarAdminTab(\'dscore\');\n    } catch (e) {\n      document.getElementById(\'dscoreError\').textContent = e.message;\n    }\n  });\n}\n\nfunction renderGeotabAdmin(tabsHtml, config) {',
