LABORATORIO_ESTUDIANTES_HTML = '<!DOCTYPE html>\n<html lang="es">\n<head>\n<meta charset="UTF-8" />\n<meta name="viewport" content="width=device-width, initial-scale=1.0" />\n<meta name="color-scheme" content="dark" />\n<title>Laboratorio — Portal de estudiantes</title>\n<style>\n  * { box-sizing: border-box; color-scheme: dark; }\n  :root {\n    --copper-light: #F0374F; --copper-dark: #A81222; --copper: #D8192F;\n    --radius-sm: 5px; --radius: 8px; --radius-lg: 14px;\n    --shadow-sm: 0 1px 2px rgba(0,0,0,0.45);\n    --shadow-md: 0 4px 10px rgba(0,0,0,0.45);\n    --shadow-inset: inset 0 1px 0 rgba(255,255,255,0.06), inset 0 -1px 0 rgba(0,0,0,0.35);\n  }\n  html, body { margin:0; padding:0; min-height:100%; background:#0B0C0D; color:#EDEDED; font-family:\'IBM Plex Sans\',\'Segoe UI\',sans-serif; }\n  body { padding:20px 16px 60px; max-width:560px; margin:0 auto; }\n  h1 { font-size:20px; margin:0 0 2px; }\n  h2 { font-size:16px; margin:22px 0 10px; }\n  .sub { font-size:13px; color:#9B9D9F; margin-bottom:20px; }\n  .card { background:linear-gradient(180deg, #17181A, #131415); border-radius:var(--radius-lg); box-shadow:var(--shadow-md), var(--shadow-inset); padding:18px; margin-bottom:16px; }\n  .card.destacada { border:1px solid var(--copper); }\n  .field { margin-bottom:12px; }\n  label { display:block; font-size:12px; color:#9B9D9F; text-transform:uppercase; letter-spacing:0.04em; margin-bottom:5px; }\n  input, select, textarea {\n    width:100%; padding:11px 12px; border-radius:var(--radius); border:1px solid rgba(155,157,159,0.25);\n    background:#0F1011; color:#EDEDED; font-size:15px; font-family:inherit; box-shadow:var(--shadow-inset);\n  }\n  input:focus, select:focus, textarea:focus { outline:none; border-color:var(--copper); }\n  textarea { resize:vertical; min-height:60px; }\n  button { cursor:pointer; font-family:inherit; font-size:14px; font-weight:700; border:none; border-radius:var(--radius); padding:12px 16px; }\n  button.primary { width:100%; background:linear-gradient(180deg, var(--copper-light), var(--copper-dark)); color:#fff; box-shadow:var(--shadow-md), var(--shadow-inset); }\n  button.primary:active { transform: translateY(1px); }\n  button.primary:disabled { opacity:0.5; }\n  button.secondary { background:#1B1C1E; color:#EDEDED; border:1px solid rgba(155,157,159,0.3); }\n  button.link { background:none; color:var(--copper-light); padding:6px 0; font-weight:600; }\n  label.btn-file { cursor:pointer; font-family:inherit; font-size:14px; font-weight:700; border-radius:var(--radius); padding:12px 16px; background:#1B1C1E; color:#EDEDED; border:1px solid rgba(155,157,159,0.3); text-align:center; display:block; }\n  .fila { display:flex; gap:10px; }\n  .fila > * { flex:1; }\n  .error { color:#FF6B7A; font-size:13px; min-height:16px; margin-top:6px; }\n  .ok { color:#4ADE80; font-size:13px; }\n  .trabajo-item { padding:14px; border-radius:var(--radius); background:#111213; box-shadow:var(--shadow-inset); margin-bottom:10px; cursor:pointer; }\n  .trabajo-item:active { transform: translateY(1px); }\n  .trabajo-folio { font-family:\'JetBrains Mono\',monospace; font-weight:700; font-size:14px; }\n  .trabajo-estado { display:inline-block; font-size:11px; text-transform:uppercase; letter-spacing:0.04em; padding:3px 8px; border-radius:20px; background:rgba(216,25,47,0.18); color:var(--copper-light); margin-left:8px; }\n  .trabajo-meta { font-size:12px; color:#9B9D9F; margin-top:4px; }\n  .pieza-row { display:flex; gap:8px; align-items:center; padding:10px 0; border-bottom:1px solid rgba(155,157,159,0.15); }\n  .pieza-row:last-child { border-bottom:none; }\n  .pieza-diente { font-family:\'JetBrains Mono\',monospace; font-weight:700; width:34px; }\n  .pieza-info { flex:1; font-size:13px; }\n  .pieza-costo { font-family:\'JetBrains Mono\',monospace; font-size:13px; color:var(--copper-light); }\n  .empty { text-align:center; color:#6F7173; font-size:13px; padding:30px 0; }\n  .top-actions { display:flex; justify-content:space-between; align-items:center; margin-bottom:14px; }\n  .badge-precio { font-size:12px; color:#9B9D9F; margin-top:6px; }\n  .badge-reporte { display:inline-block; font-size:11px; text-transform:uppercase; letter-spacing:0.04em; padding:3px 8px; border-radius:20px; margin-top:6px; }\n  .badge-reporte.pendiente { background:rgba(240,167,35,0.18); color:#F0A723; }\n  .badge-reporte.confirmado { background:rgba(74,222,128,0.18); color:#4ADE80; }\n  .badge-reporte.rechazado { background:rgba(255,107,122,0.18); color:#FF6B7A; }\n  .comprobante-preview { width:90px; height:90px; object-fit:cover; border-radius:6px; margin-top:8px; }\n  #firmaCanvas { width:100%; height:120px; background:#0F1011; border:1px solid rgba(155,157,159,0.3); border-radius:var(--radius); touch-action:none; cursor:crosshair; }\n  #pantallaInvalida { display:none; text-align:center; padding:60px 20px; color:#9B9D9F; }\n  .hidden { display:none !important; }\n</style>\n</head>\n<body>\n\n<div id="pantallaInvalida">\n  <h1>Enlace no válido</h1>\n  <p>Pídele al laboratorio el link correcto de registro.</p>\n</div>\n\n<div id="app" class="hidden">\n\n  <!-- ---- LOGIN / REGISTRO ---- -->\n  <div id="vistaAuth">\n    <h1>🧪 Laboratorio</h1>\n    <div class="sub" id="nombreEmpresaSub">Portal de estudiantes</div>\n\n    <div class="card" id="cardLogin">\n      <h2 style="margin-top:0;">Iniciar sesión</h2>\n      <div class="field"><label>Matrícula</label><input id="li_matricula" autocomplete="username" /></div>\n      <div class="field"><label>Contraseña</label><input id="li_password" type="password" autocomplete="current-password" /></div>\n      <button class="primary" onclick="iniciarSesion()">Entrar</button>\n      <div class="error" id="li_error"></div>\n      <button class="link" onclick="mostrarRegistro()">No tengo cuenta — registrarme con mi matrícula</button>\n    </div>\n\n    <div class="card hidden" id="cardRegistro">\n      <h2 style="margin-top:0;">Crear mi cuenta</h2>\n      <p class="sub" style="margin-bottom:14px;">Tu usuario de acceso es tu matrícula de la escuela — así tu cuenta queda ligada a una identificación real.</p>\n      <div class="field"><label>Matrícula</label><input id="re_matricula" autocomplete="username" /></div>\n      <div class="field"><label>Nombre completo</label><input id="re_nombre" autocomplete="name" /></div>\n      <div class="field"><label>Teléfono (10 dígitos)</label><input id="re_telefono" autocomplete="tel" /></div>\n      <div class="field"><label>Contraseña (mínimo 6 caracteres)</label><input id="re_password" type="password" autocomplete="new-password" /></div>\n      <button class="primary" onclick="registrarse()">Crear cuenta</button>\n      <div class="error" id="re_error"></div>\n      <button class="link" onclick="mostrarLogin()">Ya tengo cuenta — iniciar sesión</button>\n    </div>\n  </div>\n\n  <!-- ---- MIS TRABAJOS (lista) ---- -->\n  <div id="vistaLista" class="hidden">\n    <div class="top-actions">\n      <div>\n        <h1 style="margin-bottom:0;">Mis trabajos</h1>\n        <div class="sub" id="saludoUsuario" style="margin-bottom:0;"></div>\n      </div>\n      <button class="secondary" onclick="cerrarSesion()">Salir</button>\n    </div>\n    <button class="primary" onclick="mostrarNuevoTrabajo()">+ Nuevo trabajo</button>\n    <div id="listaTrabajos" style="margin-top:18px;"></div>\n  </div>\n\n  <!-- ---- NUEVO TRABAJO ---- -->\n  <div id="vistaNuevo" class="hidden">\n    <div class="top-actions">\n      <h1 style="margin-bottom:0;">Nuevo trabajo</h1>\n      <button class="secondary" onclick="mostrarLista()">← Volver</button>\n    </div>\n    <div class="card" id="nt_dscoreCard" style="display:none;">\n      <h2 style="margin-top:0;">Importar desde DS Core</h2>\n      <p class="sub">Pide el código a tu maestro (el de la orden que se generó en DS Core al escanear) y captúralo aquí -- se llena solo el nombre del paciente.</p>\n      <div class="field"><label>Código de DS Core</label><input id="nt_dscore_codigo" placeholder="ej. DAA04BDC" /></div>\n      <div class="field"><label>¿Requiere factura?</label><select id="nt_dscore_factura"><option value="0">No</option><option value="1">Sí</option></select></div>\n      <div class="field"><label>¿Dónde vas a recoger tu trabajo?</label><select id="nt_dscore_sucursal_recogida"></select></div>\n      <div class="error" id="nt_dscore_error"></div>\n      <button class="primary" style="width:100%;" onclick="importarDesdeDSCore()">Importar pedido</button>\n      <p class="sub" style="margin-top:10px; margin-bottom:0;">Después de importarlo, completa el odontograma (dientes/piezas) y sube tu comprobante de pago desde el detalle del trabajo.</p>\n    </div>\n    <p class="sub" id="nt_dscoreDivisor" style="display:none; text-align:center; margin: 14px 0;">— o captúralo a mano —</p>\n    <div class="card">\n      <div class="field"><label>Nombre del paciente (opcional)</label><input id="nt_paciente" /></div>\n      <div class="field"><label>Fecha compromiso (opcional)</label><input type="date" id="nt_fecha" /></div>\n      <div class="field"><label>Folio de escaneo *</label><input id="nt_folio" placeholder="Folio del documento escaneado" /></div>\n      <div class="field"><label>¿Requiere factura?</label><select id="nt_factura"><option value="0">No</option><option value="1">Sí</option></select></div>\n      <div class="field"><label>¿Dónde vas a recoger tu trabajo?</label><select id="nt_sucursal_recogida"></select></div>\n      <div class="field"><label>Notas generales (opcional)</label><textarea id="nt_notas"></textarea></div>\n\n      <h2>Piezas / dientes a trabajar</h2>\n      <div id="nt_piezasLista"></div>\n      <div class="fila">\n        <div class="field"><label>Diente</label><input id="np_diente" placeholder="ej. 14" /></div>\n        <div class="field"><label>Tipo de trabajo</label>\n          <select id="np_tipo" onchange="actualizarPrecioSugerido()">\n            <option value="corona">Corona</option>\n            <option value="implante">Implante</option>\n            <option value="puente">Puente</option>\n            <option value="carilla">Carilla</option>\n            <option value="incrustacion">Incrustación</option>\n            <option value="otro">Otro</option>\n          </select>\n        </div>\n      </div>\n      <div class="fila">\n        <div class="field"><label>Material (opcional)</label>\n          <select id="np_material" onchange="actualizarPrecioSugerido()">\n            <option value="">—</option>\n            <option value="zirconia">Zirconia</option>\n            <option value="disilicato">Disilicato</option>\n          </select>\n        </div>\n        <div class="field"><label>Color (opcional)</label><input id="np_color" /></div>\n      </div>\n      <div class="badge-precio" id="np_precioSugerido"></div>\n      <button class="secondary" style="width:100%; margin-top:8px;" onclick="agregarPiezaLocal()">+ Agregar diente</button>\n\n      <div class="error" id="nt_error" style="margin-top:14px;"></div>\n      <button class="primary" style="margin-top:14px;" onclick="crearTrabajo()">Crear trabajo</button>\n      <p class="sub" style="margin-top:10px; margin-bottom:0;">Después de crear el trabajo, sube tu comprobante de pago desde el detalle del trabajo para que el laboratorio lo confirme.</p>\n    </div>\n  </div>\n\n  <!-- ---- DETALLE DE TRABAJO ---- -->\n  <div id="vistaDetalle" class="hidden">\n    <div class="top-actions">\n      <h1 style="margin-bottom:0;">Detalle</h1>\n      <button class="secondary" onclick="mostrarLista()">← Volver</button>\n    </div>\n    <div id="detalleContenido"></div>\n  </div>\n\n</div>\n\n<script>\n  const CODIGO = window.location.pathname.split(\'/\').filter(Boolean).pop();\n  let TOKEN = null;\n  let USUARIO = null;\n  let META = null;\n  let TRABAJOS_CACHE = [];\n  let PIEZAS_NUEVAS = [];\n  let FIRMA_VACIA = true;\n  let TRABAJO_DETALLE_ID = null;\n\n  function escapeHtml(s) {\n    return String(s == null ? \'\' : s).replace(/[&<>"\']/g, c => ({ \'&\': \'&amp;\', \'<\': \'&lt;\', \'>\': \'&gt;\', \'"\': \'&quot;\', "\'": \'&#39;\' }[c]));\n  }\n\n  function fmtDinero(n) {\n    return `$${(Number(n) || 0).toLocaleString(\'es-MX\', { minimumFractionDigits: 2 })}`;\n  }\n\n  const NOMBRES_TIPO = { corona: \'Corona\', implante: \'Implante\', puente: \'Puente\', carilla: \'Carilla\', incrustacion: \'Incrustación\', otro: \'Otro\' };\n  const NOMBRES_MATERIAL = { zirconia: \'Zirconia\', disilicato: \'Disilicato\' };\n  const NOMBRES_ESTADO = {\n    recibido: \'Recibido — falta pago y firma\', en_laboratorio: \'En laboratorio\', modelado: \'Modelado / diseño\',\n    maquila: \'Maquila (fresado)\', maquillado: \'Maquillado / acabado\', control_calidad: \'Control de calidad\',\n    envio_sucursal: \'En camino a sucursal\', listo_entrega: \'Listo para entrega\', entregado: \'Entregado\', cancelado: \'Cancelado\',\n  };\n  const NOMBRES_ESTADO_REPORTE = { pendiente: \'Pendiente de revisar\', confirmado: \'Pago confirmado\', rechazado: \'Rechazado\' };\n\n  async function api(ruta, opciones = {}) {\n    const headers = { \'Content-Type\': \'application/json\' };\n    if (TOKEN) headers[\'Authorization\'] = `Bearer ${TOKEN}`;\n    const resp = await fetch(ruta, { ...opciones, headers: { ...headers, ...(opciones.headers || {}) } });\n    if (!resp.ok) {\n      const err = await resp.json().catch(() => ({}));\n      throw new Error(err.detail || \'Ocurrió un error, intenta de nuevo.\');\n    }\n    return resp.status === 204 ? null : resp.json();\n  }\n\n  function mostrarSolo(id) {\n    [\'vistaAuth\', \'vistaLista\', \'vistaNuevo\', \'vistaDetalle\'].forEach(v => {\n      document.getElementById(v).classList.toggle(\'hidden\', v !== id);\n    });\n  }\n\n  function mostrarLogin() {\n    document.getElementById(\'cardRegistro\').classList.add(\'hidden\');\n    document.getElementById(\'cardLogin\').classList.remove(\'hidden\');\n  }\n  function mostrarRegistro() {\n    document.getElementById(\'cardLogin\').classList.add(\'hidden\');\n    document.getElementById(\'cardRegistro\').classList.remove(\'hidden\');\n  }\n\n  async function iniciarSesion() {\n    const err = document.getElementById(\'li_error\');\n    err.textContent = \'\';\n    const username = document.getElementById(\'li_matricula\').value.trim();\n    const password = document.getElementById(\'li_password\').value;\n    if (!username || !password) { err.textContent = \'Completa tu matrícula y contraseña.\'; return; }\n    try {\n      const datos = await api(\'/api/auth/login\', { method: \'POST\', body: JSON.stringify({ username, password }) });\n      if (datos.usuario.rol !== \'estudiante\') {\n        err.textContent = \'Esta cuenta no es de estudiante.\';\n        return;\n      }\n      sesionIniciada(datos);\n    } catch (e) { err.textContent = e.message; }\n  }\n\n  async function registrarse() {\n    const err = document.getElementById(\'re_error\');\n    err.textContent = \'\';\n    const payload = {\n      matricula: document.getElementById(\'re_matricula\').value.trim(),\n      nombre_completo: document.getElementById(\'re_nombre\').value.trim(),\n      telefono: document.getElementById(\'re_telefono\').value.trim(),\n      password: document.getElementById(\'re_password\').value,\n    };\n    if (!payload.matricula || !payload.nombre_completo || !payload.telefono || !payload.password) {\n      err.textContent = \'Completa todos los campos.\'; return;\n    }\n    try {\n      const datos = await api(`/api/laboratorio/estudiantes/registro/${CODIGO}`, { method: \'POST\', body: JSON.stringify(payload) });\n      sesionIniciada(datos);\n    } catch (e) { err.textContent = e.message; }\n  }\n\n  function sesionIniciada(datos) {\n    TOKEN = datos.token;\n    USUARIO = datos.usuario;\n    localStorage.setItem(\'lab_estudiante_token\', TOKEN);\n    document.getElementById(\'saludoUsuario\').textContent = `${USUARIO.nombre} · ${USUARIO.username}`;\n    cargarMeta();\n    mostrarLista();\n  }\n\n  function cerrarSesion() {\n    TOKEN = null; USUARIO = null;\n    localStorage.removeItem(\'lab_estudiante_token\');\n    mostrarSolo(\'vistaAuth\');\n    mostrarLogin();\n  }\n\n  async function cargarMeta() {\n    try { META = await api(\'/api/meta\'); } catch (e) { META = null; }\n  }\n\n  async function mostrarLista() {\n    mostrarSolo(\'vistaLista\');\n    const cont = document.getElementById(\'listaTrabajos\');\n    cont.innerHTML = \'<div class="empty">Cargando…</div>\';\n    try {\n      TRABAJOS_CACHE = await api(\'/api/laboratorio/mios\');\n      if (!TRABAJOS_CACHE.length) {\n        cont.innerHTML = \'<div class="empty">Todavía no tienes ningún trabajo — crea el primero arriba.</div>\';\n        return;\n      }\n      cont.innerHTML = TRABAJOS_CACHE.map(w => `\n        <div class="trabajo-item" onclick="verDetalle(${w.id})">\n          <div><span class="trabajo-folio">${escapeHtml(w.folio)}</span><span class="trabajo-estado">${escapeHtml(NOMBRES_ESTADO[w.estado] || w.estado)}</span></div>\n          <div class="trabajo-meta">${w.piezas.length} pieza(s) · costo total ${fmtDinero(w.costo_total)}${w.pago_registrado_en ? \' · pago registrado\' : \' · falta registrar pago\'}</div>\n        </div>\n      `).join(\'\');\n    } catch (e) {\n      cont.innerHTML = `<div class="empty">${escapeHtml(e.message)}</div>`;\n    }\n  }\n\n  function mostrarNuevoTrabajo() {\n    PIEZAS_NUEVAS = [];\n    document.getElementById(\'nt_paciente\').value = \'\';\n    document.getElementById(\'nt_fecha\').value = \'\';\n    document.getElementById(\'nt_folio\').value = \'\';\n    document.getElementById(\'nt_factura\').value = \'0\';\n    document.getElementById(\'nt_notas\').value = \'\';\n    document.getElementById(\'nt_error\').textContent = \'\';\n    document.getElementById(\'nt_dscore_codigo\').value = \'\';\n    document.getElementById(\'nt_dscore_factura\').value = \'0\';\n    document.getElementById(\'nt_dscore_error\').textContent = \'\';\n    const dscoreListo = !!(META && META.dscore_conectado_laboratorio);\n    document.getElementById(\'nt_dscoreCard\').style.display = dscoreListo ? \'block\' : \'none\';\n    document.getElementById(\'nt_dscoreDivisor\').style.display = dscoreListo ? \'block\' : \'none\';\n    renderSucursalesRecogida();\n    renderPiezasNuevas();\n    mostrarSolo(\'vistaNuevo\');\n  }\n\n  function renderSucursalesRecogida() {\n    const sucursales = (META && META.sucursales_recogida_laboratorio) || [];\n    const opciones = !sucursales.length\n      ? \'<option value="">— pídele al laboratorio que configure una sucursal —</option>\'\n      : sucursales.map(s => `<option value="${s.id}" ${s.es_recogida_default_estudiantes ? \'selected\' : \'\'}>${escapeHtml(s.nombre)}${s.es_recogida_default_estudiantes ? \' (recomendada)\' : \'\'}</option>`).join(\'\');\n    [\'nt_sucursal_recogida\', \'nt_dscore_sucursal_recogida\'].forEach(id => {\n      const sel = document.getElementById(id);\n      if (sel) sel.innerHTML = opciones;\n    });\n  }\n\n  async function importarDesdeDSCore() {\n    const err = document.getElementById(\'nt_dscore_error\');\n    err.textContent = \'\';\n    const codigo = document.getElementById(\'nt_dscore_codigo\').value.trim();\n    if (!codigo) { err.textContent = \'Escribe el código que te dio tu maestro.\'; return; }\n    const sucursalRecogida = document.getElementById(\'nt_dscore_sucursal_recogida\').value;\n    const payload = {\n      codigo,\n      requiere_factura: document.getElementById(\'nt_dscore_factura\').value === \'1\',\n      sucursal_recogida_id: sucursalRecogida ? parseInt(sucursalRecogida, 10) : null,\n    };\n    try {\n      await api(\'/api/laboratorio/mios/importar-dscore\', { method: \'POST\', body: JSON.stringify(payload) });\n      mostrarLista();\n    } catch (e) { err.textContent = e.message; }\n  }\n\n  function precioFijoBuap(tipo, material) {\n    if (!META || !META.precios_fijos_laboratorio_buap) return null;\n    const clave = `${tipo}|${(material || \'\').toLowerCase()}`;\n    return META.precios_fijos_laboratorio_buap[clave] ?? null;\n  }\n\n  function actualizarPrecioSugerido() {\n    const tipo = document.getElementById(\'np_tipo\').value;\n    const material = document.getElementById(\'np_material\').value;\n    const precio = precioFijoBuap(tipo, material);\n    const box = document.getElementById(\'np_precioSugerido\');\n    box.textContent = precio != null\n      ? `Precio fijo BUAP para ${NOMBRES_TIPO[tipo] || tipo}${material ? \' · \' + (NOMBRES_MATERIAL[material] || material) : \'\'}: ${fmtDinero(precio)}`\n      : \'Sin precio fijo para esta combinación — lo revisa el laboratorio al recibir el trabajo.\';\n  }\n  actualizarPrecioSugerido();\n\n  function agregarPiezaLocal() {\n    const diente = document.getElementById(\'np_diente\').value.trim();\n    const tipo_trabajo = document.getElementById(\'np_tipo\').value;\n    const material = document.getElementById(\'np_material\').value || null;\n    const color = document.getElementById(\'np_color\').value.trim() || null;\n    if (!diente) { alert(\'Indica el número de diente.\'); return; }\n    if (PIEZAS_NUEVAS.some(p => p.diente === diente)) { alert(\'Ese diente ya está en la lista.\'); return; }\n    const precio = precioFijoBuap(tipo_trabajo, material);\n    PIEZAS_NUEVAS.push({ diente, tipo_trabajo, material, color, notas: null, costo: precio ?? 0 });\n    document.getElementById(\'np_diente\').value = \'\';\n    document.getElementById(\'np_color\').value = \'\';\n    renderPiezasNuevas();\n  }\n\n  function quitarPiezaLocal(idx) {\n    PIEZAS_NUEVAS.splice(idx, 1);\n    renderPiezasNuevas();\n  }\n\n  function renderPiezasNuevas() {\n    const cont = document.getElementById(\'nt_piezasLista\');\n    if (!PIEZAS_NUEVAS.length) {\n      cont.innerHTML = \'<p class="sub">Todavía no agregas ningún diente.</p>\';\n      return;\n    }\n    cont.innerHTML = PIEZAS_NUEVAS.map((p, i) => `\n      <div class="pieza-row">\n        <div class="pieza-diente">${escapeHtml(p.diente)}</div>\n        <div class="pieza-info">${escapeHtml(NOMBRES_TIPO[p.tipo_trabajo] || p.tipo_trabajo)}${p.material ? \' · \' + escapeHtml(NOMBRES_MATERIAL[p.material] || p.material) : \'\'}</div>\n        <div class="pieza-costo">${fmtDinero(p.costo)}</div>\n        <button class="secondary" style="padding:6px 10px;" onclick="quitarPiezaLocal(${i})">✕</button>\n      </div>\n    `).join(\'\');\n  }\n\n  async function crearTrabajo() {\n    const err = document.getElementById(\'nt_error\');\n    err.textContent = \'\';\n    const folio_escaneo = document.getElementById(\'nt_folio\').value.trim();\n    if (!folio_escaneo) { err.textContent = \'El folio de escaneo es obligatorio.\'; return; }\n    const sucursalRecogida = document.getElementById(\'nt_sucursal_recogida\').value;\n    const payload = {\n      paciente_nombre: document.getElementById(\'nt_paciente\').value.trim() || null,\n      fecha_compromiso: document.getElementById(\'nt_fecha\').value || null,\n      notas: document.getElementById(\'nt_notas\').value.trim() || null,\n      folio_escaneo,\n      requiere_factura: document.getElementById(\'nt_factura\').value === \'1\',\n      piezas: PIEZAS_NUEVAS,\n      sucursal_recogida_id: sucursalRecogida ? parseInt(sucursalRecogida, 10) : null,\n    };\n    try {\n      await api(\'/api/laboratorio/mios\', { method: \'POST\', body: JSON.stringify(payload) });\n      mostrarLista();\n    } catch (e) { err.textContent = e.message; }\n  }\n\n  function _seccionPagoYFirma(w) {\n    const faltante = Math.round((w.costo_total - w.pago_monto_total) * 100) / 100;\n    const cubierto = w.pago_registrado_en && faltante <= 0;\n    const reportes = w.pagos_reportados || [];\n    const ultimoReporte = reportes[0] || null;\n    const hayReportePendiente = ultimoReporte && ultimoReporte.estado === \'pendiente\';\n\n    let html = \'\';\n\n    if (w.estado !== \'recibido\') {\n      // Ya entró a laboratorio — el pago y la firma ya quedaron resueltos.\n      return \'\';\n    }\n\n    if (!cubierto) {\n      html += `\n        <div class="card destacada">\n          <h2 style="margin-top:0;">Pago</h2>\n          <p class="trabajo-meta">Costo total ${fmtDinero(w.costo_total)}${w.pago_monto_total > 0 ? ` · ya registrado ${fmtDinero(w.pago_monto_total)} · falta ${fmtDinero(faltante)}` : \'\'}</p>\n          ${hayReportePendiente ? `\n            <p class="badge-reporte pendiente">Reportaste un pago — pendiente de que el laboratorio lo confirme contra el banco</p>\n            ${ultimoReporte.monto_detectado != null || ultimoReporte.referencia_detectada ? `\n              <p class="trabajo-meta">Lo que se alcanzó a leer: ${ultimoReporte.monto_detectado != null ? fmtDinero(ultimoReporte.monto_detectado) : \'—\'}${ultimoReporte.referencia_detectada ? \' · ref. \' + escapeHtml(ultimoReporte.referencia_detectada) : \'\'}</p>\n            ` : \'\'}\n          ` : `\n            ${ultimoReporte && ultimoReporte.estado === \'rechazado\' ? `\n              <p class="badge-reporte rechazado">Tu último comprobante fue rechazado${ultimoReporte.motivo_rechazo ? \': \' + escapeHtml(ultimoReporte.motivo_rechazo) : \'\'} — sube uno nuevo o pasa a la sucursal.</p>\n            ` : \'\'}\n            <p class="sub" style="margin:10px 0 8px;">Sube la foto o captura de tu comprobante de transferencia (SPEI, app del banco, etc.) — el laboratorio la revisa contra el banco antes de darla por buena. También puedes pasar a pagar en persona.</p>\n            <label class="btn-file">\n              📎 Subir comprobante de transferencia\n              <input type="file" accept="image/*" style="display:none;" onchange="subirComprobantePago(${w.id}, this)" />\n            </label>\n            <div class="error" id="pagoError"></div>\n          `}\n        </div>\n      `;\n    }\n\n    if (cubierto && !w.firma_recepcion) {\n      html += `\n        <div class="card destacada">\n          <h2 style="margin-top:0;">Firma de recepción</h2>\n          <p class="sub" style="margin-bottom:10px;">Tu pago ya está confirmado — firma aquí para que el laboratorio empiece a fabricar tu trabajo.</p>\n          <canvas id="firmaCanvas" width="500" height="120"></canvas>\n          <div class="fila" style="margin-top:10px;">\n            <button class="secondary" onclick="limpiarFirma()">Limpiar</button>\n            <button class="primary" onclick="firmarRecepcion(${w.id})">Firmar y confirmar recepción</button>\n          </div>\n          <div class="error" id="firmaError"></div>\n        </div>\n      `;\n    }\n\n    return html;\n  }\n\n  async function verDetalle(id) {\n    mostrarSolo(\'vistaDetalle\');\n    TRABAJO_DETALLE_ID = id;\n    const cont = document.getElementById(\'detalleContenido\');\n    cont.innerHTML = \'<div class="empty">Cargando…</div>\';\n    try {\n      const w = await api(`/api/laboratorio/mios/${id}`);\n      cont.innerHTML = `\n        <div class="card">\n          <div><span class="trabajo-folio">${escapeHtml(w.folio)}</span><span class="trabajo-estado">${escapeHtml(NOMBRES_ESTADO[w.estado] || w.estado)}</span></div>\n          <p class="trabajo-meta">Folio de escaneo: ${escapeHtml(w.folio_escaneo || \'—\')} · Factura: ${w.requiere_factura ? \'Sí\' : \'No\'}</p>\n          ${w.sucursal_nombre ? `<p class="trabajo-meta">Recoges en: ${escapeHtml(w.sucursal_nombre)}</p>` : \'\'}\n          ${w.paciente_nombre ? `<p class="trabajo-meta">Paciente: ${escapeHtml(w.paciente_nombre)}</p>` : \'\'}\n          ${w.notas ? `<p class="trabajo-meta">Notas: ${escapeHtml(w.notas)}</p>` : \'\'}\n          <p class="trabajo-meta">${w.pago_registrado_en ? `Pago registrado (${fmtDinero(w.pago_monto_total)} de ${fmtDinero(w.costo_total)})` : \'Todavía falta que se confirme tu pago\'}</p>\n          <p class="trabajo-meta">${w.firma_recepcion ? \'Ya firmaste de recepción\' : \'Todavía falta firmar de recepción\'}</p>\n          <h2>Piezas — costo total ${fmtDinero(w.costo_total)}</h2>\n          ${w.piezas.length ? w.piezas.map(p => `\n            <div class="pieza-row">\n              <div class="pieza-diente">${escapeHtml(p.diente)}</div>\n              <div class="pieza-info">${escapeHtml(NOMBRES_TIPO[p.tipo_trabajo] || p.tipo_trabajo)}${p.material ? \' · \' + escapeHtml(NOMBRES_MATERIAL[p.material] || p.material) : \'\'}</div>\n              <div class="pieza-costo">${fmtDinero(p.costo)}</div>\n            </div>\n          `).join(\'\') : \'<p class="sub">Sin piezas todavía.</p>\'}\n        </div>\n        ${_seccionPagoYFirma(w)}\n      `;\n      const canvas = document.getElementById(\'firmaCanvas\');\n      if (canvas) {\n        FIRMA_VACIA = true;\n        inicializarFirmaCanvas(canvas);\n      }\n    } catch (e) {\n      cont.innerHTML = `<div class="empty">${escapeHtml(e.message)}</div>`;\n    }\n  }\n\n  function inicializarFirmaCanvas(canvas) {\n    const ctx = canvas.getContext(\'2d\');\n    ctx.strokeStyle = \'#EDEDED\'; ctx.lineWidth = 2; ctx.lineCap = \'round\';\n    const pos = (e) => {\n      const r = canvas.getBoundingClientRect();\n      const p = e.touches ? e.touches[0] : e;\n      return { x: (p.clientX - r.left) * (canvas.width / r.width), y: (p.clientY - r.top) * (canvas.height / r.height) };\n    };\n    let dibujando = false;\n    const empezar = (e) => { e.preventDefault(); dibujando = true; FIRMA_VACIA = false; const p = pos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); };\n    const dibujar = (e) => { if (!dibujando) return; e.preventDefault(); const p = pos(e); ctx.lineTo(p.x, p.y); ctx.stroke(); };\n    const terminar = () => { dibujando = false; };\n    canvas.onmousedown = empezar; canvas.onmousemove = dibujar; canvas.onmouseup = terminar; canvas.onmouseleave = terminar;\n    canvas.ontouchstart = empezar; canvas.ontouchmove = dibujar; canvas.ontouchend = terminar;\n  }\n\n  function limpiarFirma() {\n    const canvas = document.getElementById(\'firmaCanvas\');\n    if (!canvas) return;\n    canvas.getContext(\'2d\').clearRect(0, 0, canvas.width, canvas.height);\n    FIRMA_VACIA = true;\n  }\n\n  async function subirComprobantePago(id, input) {\n    const archivo = input.files[0];\n    if (!archivo) return;\n    const err = document.getElementById(\'pagoError\');\n    if (err) err.textContent = \'\';\n    try {\n      const comprobante_base64 = await new Promise((res, rej) => {\n        const r = new FileReader();\n        r.onload = () => res(r.result);\n        r.onerror = rej;\n        r.readAsDataURL(archivo);\n      });\n      await api(`/api/laboratorio/mios/${id}/reportar-pago`, { method: \'POST\', body: JSON.stringify({ comprobante_base64 }) });\n      await verDetalle(id);\n    } catch (e) {\n      if (err) err.textContent = e.message;\n    }\n  }\n\n  async function firmarRecepcion(id) {\n    const err = document.getElementById(\'firmaError\');\n    if (FIRMA_VACIA) { err.textContent = \'Falta tu firma.\'; return; }\n    const firma_recepcion = document.getElementById(\'firmaCanvas\').toDataURL(\'image/png\');\n    try {\n      await api(`/api/laboratorio/${id}/firmar-recepcion`, { method: \'POST\', body: JSON.stringify({ firma_recepcion }) });\n      await verDetalle(id);\n    } catch (e) {\n      err.textContent = e.message;\n    }\n  }\n\n  async function iniciar() {\n    try {\n      const info = await api(`/api/laboratorio/estudiantes/info/${CODIGO}`);\n      document.getElementById(\'nombreEmpresaSub\').textContent = `Portal de estudiantes — ${info.empresa_nombre}`;\n    } catch (e) {\n      document.getElementById(\'pantallaInvalida\').style.display = \'block\';\n      return;\n    }\n    document.getElementById(\'app\').classList.remove(\'hidden\');\n    const tokenGuardado = localStorage.getItem(\'lab_estudiante_token\');\n    if (tokenGuardado) {\n      TOKEN = tokenGuardado;\n      try {\n        USUARIO = await api(\'/api/auth/me\');\n        if (USUARIO.rol !== \'estudiante\') throw new Error(\'rol inválido\');\n        document.getElementById(\'saludoUsuario\').textContent = `${USUARIO.nombre} · ${USUARIO.username}`;\n        await cargarMeta();\n        mostrarLista();\n        return;\n      } catch (e) {\n        TOKEN = null;\n        localStorage.removeItem(\'lab_estudiante_token\');\n      }\n    }\n    mostrarSolo(\'vistaAuth\');\n  }\n\n  iniciar();\n</script>\n</body>\n</html>\n'

DSCORE_PY_CONTENT = '# -*- coding: utf-8 -*-\n"""Integración con la API de DS Core (Dentsply Sirona) para el módulo de\nLaboratorio -- deja que el estudiante importe su pedido (paciente, tipo de\ntrabajo, archivos) a partir del código que le da su maestro, en vez de\nescribirlo todo a mano. Mismo patrón que shopify_api.py: funciones puras\nque reciben los datos de conexión como parámetro, sin tocar la base de\ndatos directamente (eso lo hace app.py/db.py, igual que con Shopify).\n\nSe conecta UNA sola vez por empresa, como cuenta de servicio del\nlaboratorio (Administrar → Laboratorio → DS Core) -- no es un login por\ncada estudiante.\n\nDocumentación usada (portal de desarrolladores, persona LAB, pestaña\n"GET STARTED"):\n  - Login/autorizar:  GET  https://{base_host}/secureLogin?client_id=...&code_challenge=...&redirect_uri=...&state=...\n  - Canjear tokens:   POST https://api.dscore.com/v1beta/auth/token\n  - Refrescar tokens: POST https://api.dscore.com/v1beta/auth/token:refresh\n  - Pedidos:          GET  https://{base_host}/v1beta/orders\n  - Paciente (FHIR):  GET  https://{base_host}/v1beta/fhir/Patient/{id}\n\nHosts de sandbox confirmados: base_host = https://api.r2.dscore.com,\nglobal host (fijo, no cambia por región) = https://api.dscore.com.\n\n⚠️ Programado con base en la documentación oficial, pero TODAVÍA NO se\npudo probar contra el sandbox real (seguimos esperando a que aprueben el\nacceso -- ver Administrar → Laboratorio → DS Core). En cuanto haya\ncredenciales reales, hay que confirmar sobre todo:\n  - si el filtro readableId="..." funciona tal cual en /v1beta/orders\n    (si no, buscar_order_por_codigo ya trae un respaldo que revisa los\n    pedidos más recientes a mano)\n  - si code_challenge_method debe mandarse explícito en la URL de login\n    (se asume S256, el método estándar de PKCE)\n"""\nimport base64\nimport hashlib\nimport secrets\nimport urllib.parse\n\nimport requests\n\nTIMEOUT = 20\nGLOBAL_HOST = "https://api.dscore.com"  # fijo -- mismo para sandbox y todas las regiones de producción\n\n\nclass DSCoreError(Exception):\n    pass\n\n\ndef generar_pkce():\n    """Regresa (code_verifier, code_challenge) para el login con PKCE,\n    método S256 (el estándar de RFC 7636)."""\n    code_verifier = secrets.token_urlsafe(64)[:128]\n    digest = hashlib.sha256(code_verifier.encode("ascii")).digest()\n    code_challenge = base64.urlsafe_b64encode(digest).decode("ascii").rstrip("=")\n    return code_verifier, code_challenge\n\n\ndef armar_url_login(base_host, client_id, redirect_uri, code_challenge, state):\n    return (\n        f"{base_host.rstrip(\'/\')}/secureLogin"\n        f"?client_id={urllib.parse.quote(client_id)}"\n        f"&code_challenge={urllib.parse.quote(code_challenge)}"\n        f"&redirect_uri={urllib.parse.quote(redirect_uri)}"\n        f"&state={urllib.parse.quote(state)}"\n    )\n\n\ndef intercambiar_code_por_tokens(client_id, client_secret, redirect_uri, code, code_verifier):\n    body = {"code": code, "client_id": client_id, "redirect_uri": redirect_uri, "code_verifier": code_verifier}\n    if client_secret:\n        body["client_secret"] = client_secret\n    try:\n        r = requests.post(f"{GLOBAL_HOST}/v1beta/auth/token", json=body, timeout=TIMEOUT)\n    except requests.RequestException as e:\n        raise DSCoreError(f"No se pudo conectar con DS Core: {e}")\n    if not r.ok:\n        raise DSCoreError(f"DS Core rechazó el código ({r.status_code}): {r.text[:300]}")\n    datos = r.json()\n    return datos.get("accessToken"), datos.get("refreshToken"), datos.get("expiresIn")\n\n\ndef refrescar_tokens(client_id, client_secret, refresh_token):\n    body = {"refreshToken": refresh_token, "clientId": client_id}\n    if client_secret:\n        body["clientSecret"] = client_secret\n    try:\n        r = requests.post(f"{GLOBAL_HOST}/v1beta/auth/token:refresh", json=body, timeout=TIMEOUT)\n    except requests.RequestException as e:\n        raise DSCoreError(f"No se pudo renovar la conexión con DS Core: {e}")\n    if not r.ok:\n        raise DSCoreError(f"DS Core rechazó la renovación ({r.status_code}): {r.text[:300]}")\n    datos = r.json()\n    return datos.get("accessToken"), datos.get("refreshToken"), datos.get("expiresIn")\n\n\ndef _get(base_host, access_token, ruta, params=None):\n    try:\n        r = requests.get(\n            f"{base_host.rstrip(\'/\')}{ruta}", params=params,\n            headers={"Authorization": f"Bearer {access_token}", "Accept": "application/json"},\n            timeout=TIMEOUT,\n        )\n    except requests.RequestException as e:\n        raise DSCoreError(f"No se pudo conectar con DS Core: {e}")\n    if not r.ok:\n        raise DSCoreError(f"DS Core respondió con error ({r.status_code}) en {ruta}: {r.text[:300]}")\n    return r.json()\n\n\ndef buscar_order_por_codigo(base_host, access_token, codigo):\n    """Busca el pedido cuyo código legible (readableId) es \'codigo\'. Si el\n    filtro directo no lo encuentra, revisa entre los pedidos más recientes\n    a mano (hasta 200, por si el filtro de DS Core no soporta readableId\n    tal cual -- pendiente de confirmar con credenciales reales)."""\n    codigo = (codigo or "").strip()\n    if not codigo:\n        return None\n    try:\n        datos = _get(base_host, access_token, "/v1beta/orders", params={"filter": f\'readableId="{codigo}"\', "pageSize": 5})\n        for order in datos.get("orders", []):\n            if (order.get("readableId") or "").strip().lower() == codigo.lower():\n                return order\n    except DSCoreError:\n        pass\n    page_token = None\n    for _ in range(2):\n        params = {"pageSize": 100}\n        if page_token:\n            params["pageToken"] = page_token\n        datos = _get(base_host, access_token, "/v1beta/orders", params=params)\n        for order in datos.get("orders", []):\n            if (order.get("readableId") or "").strip().lower() == codigo.lower():\n                return order\n        page_token = datos.get("nextPageToken")\n        if not page_token:\n            break\n    return None\n\n\ndef nombre_paciente_de_order(base_host, access_token, order):\n    """El pedido solo trae la URI del paciente (ej. "fhir/Patient/123") --\n    hay que pedirlo aparte para sacar su nombre. Si algo falla, no truena\n    la importación completa -- solo se queda sin nombre prellenado."""\n    patient_uri = (order.get("patient") or {}).get("uri")\n    if not patient_uri:\n        return None\n    try:\n        datos = _get(base_host, access_token, f"/v1beta/{patient_uri}")\n    except DSCoreError:\n        return None\n    nombres = datos.get("name") or []\n    if not nombres:\n        return None\n    given = " ".join(nombres[0].get("given") or [])\n    family = nombres[0].get("family") or ""\n    nombre = f"{given} {family}".strip()\n    return nombre or None\n\n\ndef probar_conexion(base_host, access_token):\n    try:\n        _get(base_host, access_token, "/v1beta/orders", params={"pageSize": 1})\n    except DSCoreError as e:\n        return False, str(e)\n    return True, "Conectado correctamente con DS Core."\n'


def leer(ruta):
    with open(ruta, "r", encoding="utf-8", newline=None) as f:
        return f.read()


def escribir(ruta, contenido):
    with open(ruta, "w", encoding="utf-8", newline="") as f:
        f.write(contenido)


def aplicar_reemplazos(ruta):
    reemplazos = ARCHIVOS[ruta]
    try:
        contenido = leer(ruta)
    except FileNotFoundError:
        print(f"[{ruta}] No encontre el archivo -- corre esto desde la carpeta del repo.")
        return False
    cambios = 0
    hubo_error = False
    for viejo, nuevo in reemplazos:
        if nuevo in contenido:
            continue
        if viejo not in contenido:
            print(f"[{ruta}] No encontre un bloque esperado (el archivo pudo haber cambiado). Avisale a Claude.")
            hubo_error = True
            continue
        contenido = contenido.replace(viejo, nuevo, 1)
        cambios += 1
    escribir(ruta, contenido)
    print(f"[{ruta}] {cambios} cambio(s) aplicado(s).")
    return not hubo_error


def actualizar_archivo_completo(ruta, contenido_nuevo, etiqueta):
    if os.path.exists(ruta):
        actual = leer(ruta)
        if actual.strip() == contenido_nuevo.strip():
            print(f"[{ruta}] Ya esta actualizado. No hace falta nada.")
            return True
    escribir(ruta, contenido_nuevo)
    print(f"[{ruta}] Archivo actualizado ({etiqueta}).")
    return True


def main():
    ok = True
    ok = aplicar_reemplazos("backend/db.py") and ok
    ok = aplicar_reemplazos("backend/app.py") and ok
    ok = aplicar_reemplazos("frontend/index.html") and ok
    ok = actualizar_archivo_completo("frontend/laboratorio_estudiantes.html", LABORATORIO_ESTUDIANTES_HTML, "importar pedido desde DS Core") and ok
    ok = actualizar_archivo_completo("backend/dscore.py", DSCORE_PY_CONTENT, "modulo nuevo de conexion con DS Core") and ok

    if not ok:
        print()
        print("Algo no se pudo aplicar automaticamente. Avisale a Claude que mensaje salio, sin correr git add/commit todavia.")
        sys.exit(1)

    print()
    print("Todo listo. Ahora corre:")
    print("   git add backend/db.py backend/app.py backend/dscore.py frontend/index.html frontend/laboratorio_estudiantes.html")
    print('   git commit -m "Laboratorio: integracion con DS Core (login OAuth2+PKCE, importar pedido por codigo del maestro)"')
    print("   git push")


if __name__ == "__main__":
    main()
